function normalizeBrand(b) {
  const s = String(b || "").trim().toUpperCase();
  if (!s) return "";
  if (s.includes("SAMSUNG")) return "SAMSUNG";
  if (s.includes("SOUNDCORE") || s.includes("ANKER")) return "SOUNDCORE";
  if (s.includes("UGREEN")) return "UGREEN";
  if (s.includes("FOCUS")) return "FOCUS";
  if (s.includes("HISHIELD")) return "HISHIELD";
  return s;
}

function normalizeProductType(t, item) {
  const s = String(t || "").trim().toUpperCase();
  if (s.includes("SPEAKER")) return "BLUETOOTH_SPEAKER";
  if (s.includes("PHONE") || s.includes("SMARTPHONE")) return "SMARTPHONE";
  if (s.includes("TABLET") || s.includes("TAB")) return "TABLET";
  if (s.includes("WATCH")) return "WATCH";
  if (s.includes("BUDS") || s.includes("EARBUDS") || s.includes("HEADPHONE")) return "EARBUDS";
  if (s.includes("ADAPTER") || s.includes("CHARGER")) return "ADAPTER";
  if (s.includes("CASE") || s.includes("FILM") || s.includes("ACCESSORY")) return "ACCESSORY";
  if (s.includes("PREMIUM") || s.includes("GIFT")) return "PREMIUM_GIFT";

  if (item) {
    const c1 = String(item.category1 || "").toUpperCase();
    const c2 = String(item.category2 || "").toUpperCase();
    const m = String(item.model || "").toUpperCase();
    if (c2.includes("SPEAKER") || m.includes("SPEAKER") || m.includes("SOUNDCORE")) return "BLUETOOTH_SPEAKER";
    if (c1.includes("PHONE") || m.includes("GALAXY S") || m.includes("GALAXY A") || m.includes("GALAXY Z")) return "SMARTPHONE";
    if (c1.includes("TABLET") || m.includes("GALAXY TAB")) return "TABLET";
    if (c1.includes("WATCH") || m.includes("GALAXY WATCH")) return "WATCH";
    if (c1.includes("AUDIO") && (m.includes("BUDS") || c2.includes("HEADPHONE"))) return "EARBUDS";
  }
  return s || "OTHER";
}

function validateSpecMatch(stockItem, specRecord, matchLevel = "NO_MATCH") {
  if (!stockItem || !specRecord) {
    return { passed: false, errors: ["MISSING_DATA"] };
  }
  const errors = [];
  const stockBrand = normalizeBrand(stockItem.brand || (stockItem.model && stockItem.model.toUpperCase().includes("SOUNDCORE") ? "SOUNDCORE" : "SAMSUNG"));
  const specBrand = normalizeBrand(specRecord.brand || (specRecord.officialName && specRecord.officialName.toUpperCase().includes("SOUNDCORE") ? "SOUNDCORE" : "SAMSUNG"));

  if (stockBrand && specBrand && stockBrand !== specBrand) {
    errors.push("BRAND_MISMATCH");
  }

  const stockType = normalizeProductType(stockItem.productType || stockItem.category || stockItem.category1, stockItem);
  const specType = normalizeProductType(specRecord.productType || specRecord.category);

  const accessorySubtypes = new Set([
    "ACCESSORY",
    "BLUETOOTH_SPEAKER",
    "ADAPTER",
    "EARBUDS",
    "PREMIUM_GIFT"
  ]);

  const isVerifiedExactAccessoryCompatibility =
    matchLevel === "EXACT_ACCESSORY_PN" &&
    stockType === "ACCESSORY" &&
    accessorySubtypes.has(specType);

  if (
    stockType !== "OTHER" &&
    specType !== "OTHER" &&
    stockType !== specType &&
    !isVerifiedExactAccessoryCompatibility
  ) {
    errors.push("PRODUCT_TYPE_MISMATCH");
  }

  return {
    passed: errors.length === 0,
    errors
  };
}

window.validateSpecMatch = validateSpecMatch;
window.normalizeBrand = normalizeBrand;
window.normalizeProductType = normalizeProductType;


